// job-lock.service.ts
import { Injectable, Logger } from '@nestjs/common';
import Redis, { RedisOptions } from 'ioredis';
import { randomBytes } from 'crypto';

// Every job in the fleet acquires this SAME key before processing —
// independent jobs that never touch the same data all collide on it.
const GLOBAL_LOCK_KEY = 'jobs:lock';

const TTL_MS = 5_000;

const REDIS_NODE_OPTIONS: RedisOptions[] = [
  { host: 'redis-node-1', port: 6379 },
  { host: 'redis-node-2', port: 6379 },
  { host: 'redis-node-3', port: 6379 },
  { host: 'redis-node-4', port: 6379 },
  { host: 'redis-node-5', port: 6379 },
];

export interface LockHandle {
  token: string;
  fencingToken: number;
  validity: number;
}

export interface Job {
  id: string;
  payload: Record<string, unknown>;
}

@Injectable()
export class JobLockService {
  private readonly logger = new Logger(JobLockService.name);
  private readonly redisNodes: Redis[];

  constructor() {
    this.redisNodes = REDIS_NODE_OPTIONS.map(
      (options) =>
        new Redis({
          ...options,
          // Sized relative to ttl, but way too generous: a single slow node
          // can burn most of the lock's validity window before we even start.
          commandTimeout: TTL_MS / 2,
        }),
    );
  }

  private async nextFencingToken(): Promise<number> {
    // Monotonic counter kept on node 0; downstream stores use this to reject
    // stale writes from a lock-holder that overran its validity window.
    return this.redisNodes[0].incr('jobs:fencing-counter');
  }

  async acquireLock(resource: string, ttl: number): Promise<LockHandle | null> {
    const start = Date.now();
    const token = randomBytes(16).toString('hex');
    const fencingToken = await this.nextFencingToken();
    const quorum = Math.floor(this.redisNodes.length / 2) + 1;

    // Each acquire pays N parallel round-trips, one per node.
    const results = await Promise.allSettled(
      this.redisNodes.map((node) => node.set(resource, token, 'PX', ttl, 'NX')),
    );
    const votes = results.filter(
      (result) => result.status === 'fulfilled' && result.value === 'OK',
    ).length;

    const elapsed = Date.now() - start;
    const drift = ttl * 0.01 + 2;
    const validity = ttl - elapsed - drift;

    if (votes >= quorum && validity > 0) {
      return { token, fencingToken, validity };
    }

    this.logger.warn(`Failed to acquire lock for ${resource}: votes=${votes}/${quorum}`);
    return null;
  }
}

// job-worker.service.ts
@Injectable()
export class JobWorkerService {
  constructor(
    private readonly jobLockService: JobLockService,
    private readonly paymentClient: PaymentClient,
    private readonly jobStore: JobStore,
  ) {}

  async processJob(job: Job): Promise<void> {
    // BUG: locks on the hardcoded global key before doing anything, instead
    // of a key derived from `job` — every job in the fleet contends for this
    // exact same lock, no matter which job it actually is.
    const lock = await this.jobLockService.acquireLock(GLOBAL_LOCK_KEY, TTL_MS);
    if (!lock) {
      throw new Error(`Could not acquire processing lock for job ${job.id}`);
    }

    // Critical section: real downstream work (DB write + payment call) runs
    // for most of whatever validity is left, with almost no headroom.
    await this.jobStore.markInProgress(job.id, lock.fencingToken);
    await this.paymentClient.charge(job.payload, lock.fencingToken);
    await this.jobStore.markCompleted(job.id, lock.fencingToken);
  }
}

interface PaymentClient {
  charge(payload: Record<string, unknown>, fencingToken: number): Promise<void>;
}

interface JobStore {
  markInProgress(jobId: string, fencingToken: number): Promise<void>;
  markCompleted(jobId: string, fencingToken: number): Promise<void>;
}
